_US_STATES = ("alabama alaska arizona arkansas california colorado connecticut delaware florida georgia hawaii idaho "
              "illinois indiana iowa kansas kentucky louisiana maine maryland massachusetts michigan minnesota "
              "mississippi missouri montana nebraska nevada ohio oklahoma oregon pennsylvania tennessee texas utah "
              "vermont virginia wisconsin wyoming").split()


def _jitter(seed, amount=0.6):
    h = hashlib.md5(seed.encode()).digest()
    return (h[0] / 255.0 - 0.5) * amount, (h[1] / 255.0 - 0.5) * amount


def locate(location):
    """Return {'latitude', 'longitude', 'country_code'?} for a free-text location, or {}."""
    if not location:
        return {}
    text = location.lower()
    lat_lon = None
    for city, coords in CITIES.items():
        if re.search(r"\b%s\b" % re.escape(city), text):
            lat_lon = coords
            break
    if not lat_lon:
        names = {k.lower(): k for k in COUNTRIES}
        for alias, name in ALIASES.items():
            names.setdefault(alias, name)
        # longest names first so "south sudan" wins over "sudan"
        for key in sorted(names, key=len, reverse=True):
            if re.search(r"\b%s\b" % re.escape(key), text):
                lat_lon = COUNTRIES.get(names[key])
                break
        if not lat_lon and any(re.search(r"\b%s\b" % s, text) for s in _US_STATES):
            lat_lon = COUNTRIES["United States of America"]
    if not lat_lon:
        return {}
    dy, dx = _jitter(location)
    return {"latitude": round(lat_lon[0] + dy, 4), "longitude": round(lat_lon[1] + dx, 4)}
